n        }\r\n    }\r\n\r\n    &__cantidad {\r\n        display: block;\r\n        width: 75%;\r\n\r\n        @include desktop {\r\n            margin-left: 4rem;\r\n\r\n        }\r\n\r\n        label {\r\n            color: $negro;\r\n        }\r\n    }\r\n\r\n    .contenido {\r\n        background-color: darken($gris-formulario, 50%);\r\n\r\n        h3 {\r\n            color: $negro;\r\n            font-weight: $bold;\r\n        }\r\n\r\n        li {\r\n            list-style: none;\r\n        }\r\n\r\n        h4 {\r\n            color: $negro;\r\n        }\r\n    }\r\n}\r\n\r\n.resumen__pedido {\r\n    h3{\r\n        color: $negro;\r\n        font-weight: $bold;\r\n    }\r\n\r\n\r\n\r\n\r\n    .resumen {\r\n        display: grid;\r\n        border: 2rem;\r\n        border-radius: .5rem;\r\n\r\n        @include telefono {\r\n            grid-template-columns: repeat(1, 1fr);\r\n            gap: 5rem;\r\n        }\r\n\r\n        @include telefono {\r\n            grid-template-columns: repeat(2, 1fr);\r\n            gap: 5rem;\r\n        }\r\n\r\n        background-color: lighten($gris-formulario, 10);\r\n\r\n        h3 {\r\n            display: block;\r\n            color: $negro;\r\n            font-weight: $bold;\r\n        }\r\n\r\n        h4 {\r\n            margin: 0rem 1rem;\r\n        }\r\n\r\n        .porcentaje {\r\n            display: flex;\r\n            padding: 0.5rem;\r\n\r\n            input[type=\"radio\"] {\r\n                display: none;\r\n            }\r\n\r\n            label {\r\n                position: relative;\r\n                color: #01cc65;\r\n                font-weight: $bold;\r\n                font-family: 'Poppins', sans-serif;\r\n                font-size: 3rem;\r\n                border: 3px solid #01cc65;\r\n                border-radius: .5rem;\r\n                padding: 1rem 5rem;\r\n                display: flex;\r\n                align-items: center;\r\n                cursor: pointer;\r\n\r\n            }\r\n\r\n            label:before {\r\n                content: \"\";\r\n                height: 3rem;\r\n                width: 3rem;\r\n                border: .35rem solid darken(#01cc65, 15);\r\n                border-radius: 50%;\r\n                margin-right: 2rem;\r\n                display: flex;\r\n                align-items: center;\r\n                justify-content: center;\r\n            }\r\n\r\n            label:after {\r\n                content: \"\";\r\n                height: 1.6rem;\r\n                width: 1.6rem;\r\n                background-color: white;\r\n                border-radius: 50%;\r\n                display: none;\r\n\r\n            }\r\n\r\n            input[type=\"radio\"]:checked+label {\r\n                display: flex;\r\n                align-items: center;\r\n                justify-content: center;\r\n                background-color: #01cc65;\r\n                color: $blanco;\r\n            }\r\n\r\n            input[type=\"radio\"]:checked+label:before {\r\n                content: \"\";\r\n                height: 1.2rem;\r\n                width: 1.2rem;\r\n                // Este es el color de fondo del mas pequeño\r\n                background-color: darken(#01cc65, 5);\r\n                border-radius: 50%;\r\n            }\r\n        }\r\n\r\n        .contenido {\r\n            h3 {\r\n                display: block;\r\n            }\r\n\r\n            border-radius: 1rem;\r\n            background-color: $blanco;\r\n\r\n            ul {\r\n\r\n                li {\r\n                    border: 3px solid darken($gris-formulario, 5);\r\n                    border-radius: .5rem;\r\n                    margin-bottom: 1rem;\r\n                    p {\r\n                        margin: 1rem;\r\n\r\n                        font-weight: $bold;\r\n                        font-size: 2rem;\r\n\r\n                        span {\r\n                            font-weight: $regular;\r\n                        }\r\n                    }\r\n                }\r\n\r\n            }\r\n        }\r\n    }\r\n\r\n\r\n    .formulario-propina {\r\n        .porcentaje {\r\n            border: 3px solid darken($gris-formulario, 5);\r\n            border-radius: .5rem;\r\n            margin: 2rem;\r\n            display: grid;\r\n            grid-template-columns: repeat(2, 1fr);\r\n            gap: 1rem;\r\n            padding: 1rem;\r\n        }\r\n        .total{\r\n            background-color: darken($gris-formulario,5);\r\n            border: 3px solid darken($gris-formulario, 5);\r\n            border-radius: .5rem;\r\n            margin: 2rem;\r\n            padding: 1rem;\r\n            p{\r\n                font-size: 3rem;\r\n                font-weight: $bold;\r\n            }\r\n\r\n        }\r\n\r\n    }\r\n}",".estadisticas {\r\n    display: grid;\r\n\r\n    @include telefono {\r\n        grid-template-columns: repeat(1, 1fr);\r\n    }\r\n\r\n    @include tablet {\r\n        grid-template-columns: repeat(2, 1fr);\r\n    }\r\n\r\n    justify-content: center;\r\n    max-width: 75%;\r\n    max-height: 60%;\r\n    margin: 1rem 15%;\r\n\r\n}\r\n\r\n.ayudas {\r\n    display: grid;\r\n\r\n    @include telefono{\r\n        grid-template-columns: repeat(1,1fr);\r\n    }\r\n    @include tablet{\r\n        grid-template-columns: repeat(2,1fr);\r\n        gap: 1rem;\r\n    \r\n    }\r\n\r\n    .ayuda-estadisticas {\r\n        margin: 0rem 2rem;\r\n        ul {\r\n            list-style: none;\r\n            color: $blanco;\r\n            text-align: center;\r\n\r\n        }\r\n    }\r\n\r\n}\r\n\r\n.metricas {\r\n    padding: 2rem;\r\n    margin: 2rem;\r\n    border-radius: .5rem;\r\n\r\n    .card {\r\n\r\n        h2 {\r\n            font-size: 1.6rem;\r\n            font-weight: $bold;\r\n        }\r\n\r\n        p {\r\n            color: $blanco;\r\n            padding: 1rem;\r\n            margin: 1rem;\r\n            text-align: center;\r\n            border-radius: 2rem;\r\n            background-color: $cyan;\r\n            border: 1px solid $azul;\r\n            font-weight: $bold;\r\n        }\r\n    }\r\n}",".contenedor-11 {\r\n    width: 95%;\r\n    max-width: 80rem;\r\n    margin: 0 auto;\r\n\r\n    h1 {\r\n        margin: 0 0;\r\n        font-size: 3rem;\r\n        font-weight: $regular;\r\n    }\r\n}\r\n\r\n.seccion-11 {\r\n    margin-top: calc($separacion / 2);\r\n    margin-bottom: calc($separacion / 2);\r\n}\r\n\r\n.contenido-centrado-11 {\r\n    max-width: 90%;\r\n}\r\n\r\n.grid-container {\r\n    display: grid;\r\n    grid-template-rows: 2fr 1fr;\r\n    grid-template-columns: 2fr 1fr;\r\n    gap: 1rem;\r\n    height: 80vh;\r\n    width: auto;\r\n    margin: 0 auto;\r\n\r\n    @media (min-width: #{$telefono-1}) {\r\n        grid-template-rows: 1fr 1fr 1fr 1fr;\r\n        grid-template-columns: 1fr;\r\n    height: 200vh;\r\n\r\n\r\n    }\r\n\r\n    @media (min-width: #{$tablet}) {\r\n        grid-template-rows: auto auto auto;\r\n        grid-template-columns: 1fr;\r\n    height: 200vh;\r\n\r\n    }\r\n\r\n    @media (min-width: #{$laptop-1}) {\r\n        grid-template-rows: 2fr 1fr;\r\n        grid-template-columns: 2fr 1fr;\r\n    height: 80vh;\r\n\r\n    }\r\n}\r\n\r\nbody {\r\n    margin: 0;\r\n    padding: 0;\r\n    // box-sizing: border-box;\r\n}\r\n\r\n.grid-item {\r\n    grid-template-rows: 1fr 10fr 2fr 1fr;\r\n    grid-template-columns: 24fr 10fr;\r\n}\r\n\r\n//tabla de productos y ticket\r\n.rectangulo-grande {\r\n\r\n    grid-row: 1 / 3;\r\n    grid-column: 1 / 2;\r\n    background-color: #f4f4f4;\r\n    border: 1px solid #ccc;\r\n    border-radius: 1rem;\r\n    justify-content: center;\r\n    align-items: center;\r\n    font-size: 1.5rem;\r\n    display: grid;\r\n    box-shadow: 5px 5px 5px rgba(0, 0, 0, 0.5);\r\n\r\n    @media (min-width: #{$telefono-1}) {\r\n        grid-row: 1/2;\r\n        grid-column: 1;\r\n\r\n    }\r\n\r\n    @media (min-width: #{$tablet}) {\r\n        grid-row: 1/2;\r\n        grid-column: 1;\r\n    }\r\n\r\n    @media (min-width: #{$laptop-1}){\r\n        grid-row: 1 / 3;\r\n        grid-column: 1 / 2;\r\n    }\r\n\r\n    .rectangulo-grande-bebe1 {\r\n        grid-row: 1;\r\n        grid-column: 1;\r\n        background-color: #fff;\r\n        width: 100%;\r\n        height: 100%;\r\n        margin-top: 2rem;\r\n        margin-left: 2rem;\r\n\r\n        @media (min-width: #{$telefono-1}) {\r\n            margin-left: 0;\r\n\r\n    \r\n        }\r\n    \r\n        @media (min-width: #{$tablet}) {\r\n            margin-left: 0;\r\n\r\n        }\r\n    \r\n        @media (min-width: #{$laptop-1}){\r\n            margin-left: 2rem;\r\n\r\n        }\r\n\r\n        h3 {\r\n            margin: 5px 0 0 0;\r\n            padding: 0;\r\n            font-size: 1.7rem;\r\n\r\n        }\r\n\r\n    }\r\n\r\n    .rectangulo-grande-bebe2 {\r\n        grid-row: 2;\r\n        grid-column: 1;\r\n        width: 100%;\r\n        height: 100%;\r\n        box-shadow: 5px 5px 5px rgba(0, 0, 0, 0.5);\r\n\r\n        margin-top: 0;\r\n        padding-top: 0;\r\n        margin-left: 2rem;\r\n        overflow-x: auto;\r\n        background-color: #fff;\r\n        display: flex;\r\n        flex-direction: column;\r\n        align-items: center;\r\n        justify-content: flex-start;\r\n        @media (min-width: #{$telefono-1}) {\r\n            margin-left: 0;\r\n\r\n    \r\n        }\r\n    \r\n        @media (min-width: #{$tablet}) {\r\n            margin-left: 0;\r\n\r\n        }\r\n    \r\n        @media (min-width: #{$laptop-1}){\r\n            margin-left: 2rem;\r\n\r\n        }\r\n\r\n\r\n        .tablamg {\r\n            display: flex;\r\n            align-items: center;\r\n            width: 90%;\r\n            justify-content: center;\r\n\r\n            .ordenes {\r\n                width: 100%;\r\n                border-collapse: collapse;\r\n                table-layout: auto;\r\n                font-size: 1.2rem;\r\n\r\n                td {\r\n                    padding: 4px 1px;\r\n                    text-align: left;\r\n                    border: solid 1px #ccd1ff;\r\n                }\r\n\r\n                th {\r\n                    padding: 2px 1px;\r\n                    text-align: left;\r\n                    font-weight: bold;\r\n                    color: black;\r\n                    background: linear-gradient(to right, #d9f4e1, #f4f4f4);\r\n                    border: solid 1px #ccd1ff;\r\n                }\r\n\r\n                tbody tr:nth-child(even) {\r\n                    background-color: #fbfcff;\r\n                    cursor: pointer;\r\n\r\n                }\r\n\r\n                tbody tr:hover {\r\n                    background-color: #f6f7ff;\r\n                }\r\n\r\n                img {\r\n                    max-width: 4rem;\r\n                    max-height: 4rem;\r\n                }\r\n\r\n                .botoneditar-cantidad {\r\n                    margin-bottom: 1px;\r\n                    background-color: #1b31ff;\r\n                    color: #fff;\r\n                    padding: 1px;\r\n                    border-radius: 5px;\r\n                    display: block;\r\n                    font-weight: bold;\r\n                    text-align: center;\r\n                }\r\n\r\n                .botoneditar-cantidad:hover {\r\n                    cursor: pointer;\r\n                    background-color: #fff;\r\n                    border: solid 1px #1b31ff;\r\n                    color: #1b31ff;\r\n\r\n                }\r\n\r\n                .botoneliminar-producto {\r\n                    margin-top: 2px;\r\n                    background-color: #ff1e1e;\r\n                    color: #fff;\r\n                    padding: 1px;\r\n                    border-radius: 5px;\r\n                    display: block;\r\n                    font-weight: bold;\r\n                    text-align: center;\r\n                }\r\n\r\n                .botoneliminar-producto:hover {\r\n                    cursor: pointer;\r\n                    border: solid 1px #ff1e1e;\r\n                    background-color: #fff;\r\n                    color: #ff1e1e;\r\n                }\r\n            }\r\n        }\r\n    }\r\n\r\n    .rectangulo-grande-bebe3 {\r\n        grid-row: 3;\r\n        grid-column: 1/3;\r\n        display: grid;\r\n        grid-template-rows: auto auto;\r\n        grid-template-columns: 1fr 1fr;\r\n        column-gap: 1rem;\r\n        align-items: center;\r\n        justify-content: center;\r\n        margin-top: auto;\r\n        padding: 1rem;\r\n\r\n\r\n        .rectangulo-grande-bebecito1 {\r\n            grid-row: 1;\r\n            grid-column: 1 / 3;\r\n            display: flex;\r\n            justify-content: space-around;\r\n            align-items: center;\r\n\r\n            .flexbtnbusqueda{\r\n                display: flex;\r\n                align-items: center;\r\n                justify-content: center;\r\n                gap: 1rem;\r\n\r\n                img{\r\n                    width: 2rem;\r\n                    height: auto;\r\n                }\r\n            }\r\n\r\n\r\n            .boton-azul-block {\r\n                width: 40%;\r\n                // height: 5rem;\r\n                margin: 0 0 0 0;\r\n                text-align: center;\r\n                @include fondo-radial(#b58807);\r\n                border-radius: 1.2rem;\r\n                font-size: 1.5rem;\r\n                padding: 0.5rem 1rem;\r\n                min-height: 3.5rem;\r\n                box-shadow: 5px 5px 5px rgba(0, 0, 0, 0.5);\r\n\r\n\r\n                &:hover {\r\n                    background-color: #f4f4f4;\r\n                    cursor: pointer;\r\n                    background-image: none;\r\n                    border: solid 1px #b58807;\r\n                    color: #b58807;\r\n\r\n                    // border: solid 1px $amarillo;\r\n                    // background-color: #f4f4f4;\r\n                }\r\n            }\r\n        }\r\n\r\n        .rectangulo-grande-bebecito2 {\r\n            grid-row: 2;\r\n            grid-column: 1 / 3;\r\n            display: flex;\r\n            justify-content: center;\r\n            align-items: center;\r\n\r\n            img {\r\n                height: 1.7rem;\r\n                width: 1.7rem;\r\n            }\r\n\r\n            .boton-rojo-block {\r\n                display: flex;\r\n                width: auto;\r\n                justify-content: center;\r\n            gap: 5px;\r\n\r\n            align-items: center;\r\n                max-width: 30rem;\r\n                min-width: 17rem;\r\n                height: 3rem;\r\n                margin: 0.4rem 0 0 0;\r\n                text-align: center;\r\n                font-size: 1.5rem;\r\n                min-height: 3.5rem;\r\n                padding: 0 0 0 0;\r\n                background-color: red;\r\n                box-shadow: 5px 5px 5px rgba(0, 0, 0, 0.5);\r\n\r\n                // @include fondo-radial($rojo);\r\n                border-radius: 1.2rem;\r\n\r\n                &:hover {\r\n                    color: red;\r\n                    background-color: #f4f4f4;\r\n                    cursor: pointer;\r\n                    border: solid 1px red;\r\n                }\r\n\r\n            }\r\n        }\r\n\r\n    }\r\n\r\n    .rectangulo-grande-bebe4 {\r\n        grid-row: 4;\r\n        grid-column: 1/3;\r\n        display: flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n\r\n\r\n\r\n        .alertas {\r\n            width: 80%;\r\n            height: 100%;\r\n            background-color: #fff;\r\n            box-shadow: 0 0 10px rgba(0, 0, 0, 0.5);\r\n            border-radius: 1rem;\r\n            margin-bottom: 1rem;\r\n            padding: 0;\r\n            justify-content: center;\r\n            text-align: center;\r\n\r\n            p {\r\n                padding: 0;\r\n                font-size: 1.6rem;\r\n                font-weight: bold;\r\n                text-align: center;\r\n                justify-content: center;\r\n                margin: 0;\r\n\r\n            }\r\n\r\n            .color-verde {\r\n                color: #0a960a;\r\n            }\r\n\r\n            .color-rojo {\r\n                color: #ff0707;\r\n            }\r\n\r\n            .color-negro {\r\n                color: black;\r\n            }\r\n        }\r\n\r\n    }\r\n\r\n    .rectangulo-grande-bebe5 {\r\n        grid-row: 1/3;\r\n        grid-column: 2;\r\n        // background-color: #d9f4e1;\r\n        background-color: #0222b1;\r\n\r\n        height: 100%;\r\n        width: 100%;\r\n        border: solid 1px #caf7d8;\r\n        box-shadow: 5px 5px 5px rgba(0, 0, 0, 0.5);\r\n        display: grid;\r\n        grid-template-rows: 4fr 1fr;\r\n        font-size: 9px;\r\n        overflow-x: auto;\r\n        color: #fff;\r\n\r\n\r\n        .tabla-ticket {\r\n            grid-row: 1;\r\n            margin: 5px 20px;\r\n            background-color: #0222b1;\r\n\r\n            .ticket {\r\n                table-layout: auto;\r\n                border-collapse: collapse;\r\n\r\n                td,\r\n                th {\r\n                    padding: 0;\r\n                    margin: 0;\r\n                }\r\n\r\n                td {\r\n                    padding: 3px;\r\n                }\r\n\r\n                th {\r\n                    text-align: left;\r\n                    border-bottom: dotted 2px rgb(255, 255, 255);\r\n                    border-top: dotted 2px rgb(255, 255, 255);\r\n                }\r\n\r\n                tbody tr:nth-child(even) {\r\n                    background-color: rgb(2, 28, 143);\r\n\r\n                }\r\n            }\r\n        }\r\n\r\n        .total-ticket {\r\n            grid-row: 2;\r\n            border-top: dotted 2px rgb(255, 255, 255);\r\n\r\n            display: flex;\r\n            justify-content: end;\r\n            align-items: center;\r\n            margin: 0 15px;\r\n\r\n            p {\r\n                color: #fff;\r\n            }\r\n        }\r\n    }\r\n\r\n    h2 {\r\n        color: $negro;\r\n\r\n    }\r\n\r\n    h3 {\r\n        font-size: 2rem;\r\n        font-weight: $bold;\r\n    }\r\n\r\n}\r\n\r\n//detalles\r\n.rectangulo-pequeno {\r\n    grid-column: 2;\r\n    grid-row: 1;\r\n    background-color: #e0e0e0;\r\n    border: 1px solid #ccc;\r\n    border-radius: 1rem;\r\n    justify-content: center;\r\n    align-items: center;\r\n    font-size: 1.2rem;\r\n    // margin: 1rem;\r\n    display: grid;\r\n    grid-template-rows: 1fr 1fr;\r\n    grid-template-columns: 1fr 1fr;\r\n    box-shadow: 5px 5px 5px rgba(0, 0, 0, 0.5);\r\n\r\n    @media (min-width: #{$telefono-1}){\r\n\r\n        grid-row: 2/3;\r\n        grid-column: 1;\r\n\r\n    }\r\n\r\n    @media (min-width: #{$tablet}){\r\n\r\n        grid-row: 2/3;\r\n        grid-column: 1;\r\n    }\r\n\r\n    @media (min-width: #{$laptop-1}){\r\n\r\n        grid-column: 2/3;\r\n        grid-row: 1;\r\n    }\r\n\r\n\r\n    h3 {\r\n        font-size: 1rem;\r\n        font-weight: $bold;\r\n        margin: 0 0 0 0;\r\n        padding: 0 0 0 0;\r\n    }\r\n\r\n    .rectangulo-pequeno-bebe1 {\r\n        margin-left: 1rem;\r\n        grid-row: 1;\r\n        grid-column: 1;\r\n        height: 100%;\r\n        display: flex;\r\n        justify-content: center;\r\n        align-items: center;\r\n        background-color: #fff;\r\n        border-top-left-radius: 1rem;\r\n        margin-top: 2rem;\r\n        padding-left: 0;\r\n        padding-bottom: 0;\r\n        margin-bottom: 0;\r\n\r\n        @media (min-width: #{$telefono-1}){\r\n            justify-content: center;   \r\n        }\r\n        @media (min-width: #{$tablet}){\r\n            justify-content: center;     \r\n        }\r\n        @media (min-width: #{$laptop-1}){\r\n            justify-content: center;   \r\n        }\r\n\r\n\r\n        img {\r\n            max-height: 13rem;\r\n            max-width: 13rem;\r\n            border: solid 1px rgb(180, 180, 180);\r\n            box-shadow: 5px 5px 5px rgba(0, 0, 0, 0.5);\r\n        }\r\n    }\r\n\r\n    .rectangulo-pequeno-bebe2 {\r\n        grid-row: 1;\r\n        margin-right: 1rem;\r\n        grid-column: 2;\r\n        margin-top: 2rem;\r\n        border-top-right-radius: 1rem;\r\n        border-bottom-right-radius: 1rem;\r\n        grid-template-rows: auto auto;\r\n        background-color: #fff;\r\n        height: 100%;\r\n        padding-top: 1rem;\r\n        padding-right: 2rem;\r\n        display: grid;\r\n        grid-template-rows: 1fr 3fr;\r\n        gap: 0;\r\n\r\n        @media (min-width: #{$telefono-1}){\r\n            padding-left: 0;\r\n        }\r\n        @media (min-width: #{$tablet}){\r\n            padding-left: 0;\r\n\r\n        }\r\n        @media (min-width: #{$laptop-1}){\r\n            padding-left: 0;\r\n\r\n        }\r\n\r\n       \r\n\r\n        .rectangulo-pequeno-bebecito21 {\r\n            grid-row: 1;\r\n            display: flex;\r\n            justify-content: left;\r\n            align-items:flex-start;\r\n\r\n            @media (min-width: #{$telefono-1}){\r\n                justify-content: center;   \r\n            }\r\n            @media (min-width: #{$tablet}){\r\n                justify-content: center;   \r\n\r\n            }\r\n            @media (min-width: #{$laptop-1}){\r\n                justify-content: center;\r\n\r\n            }\r\n\r\n            h3 {\r\n                font-size: 1.6rem;\r\n                font-weight: $bold;\r\n                margin: 0;\r\n                padding: 0;\r\n                // text-transform: uppercase;\r\n\r\n                @media (min-width: #{$telefono-1}){\r\n                    text-align: center;   \r\n                }\r\n                @media (min-width: #{$tablet}){\r\n                    text-align: center;   \r\n \r\n                }\r\n                @media (min-width: #{$laptop-1}){\r\n                    text-align: center;\r\n  \r\n                }\r\n            }\r\n        }\r\n\r\n        .rectangulo-pequeno-bebecito22 {\r\n            grid-row: 2;\r\n            display: flex;\r\n            justify-content: left;\r\n            align-items:flex-start;\r\n\r\n            @media (min-width: #{$telefono-1}){\r\n                justify-content: center;   \r\n            }\r\n            @media (min-width: #{$tablet}){\r\n                justify-content: center;   \r\n            }\r\n            @media (min-width: #{$laptop-1}){\r\n                justify-content: center;   \r\n            }\r\n\r\n            h3 {\r\n                font-size: 1.5rem;\r\n                font-weight: normal;\r\n                margin: 0;\r\n                padding: 0;\r\n                text-align: left;\r\n\r\n                @media (min-width: #{$telefono-1}){\r\n                    text-align: center;   \r\n                }\r\n                @media (min-width: #{$tablet}){\r\n                    text-align: left;\r\n \r\n                }\r\n                @media (min-width: #{$laptop-1}){\r\n                    text-align: left;\r\n  \r\n                }\r\n            }\r\n        }\r\n    }\r\n\r\n    .rectangulo-pequeno-bebe3 {\r\n        grid-row: 2;\r\n        grid-column: 1;\r\n        display: grid;\r\n        background-color: #fff;\r\n        grid-template-rows: 1fr 2fr;\r\n        margin-left: 1rem;\r\n        height: 100%;\r\n        margin-bottom: 2rem;\r\n        border-bottom-left-radius: 1rem;\r\n        justify-content: center;\r\n        align-items: center;\r\n        padding-bottom: 1rem;\r\n        padding-left: 2rem;\r\n\r\n        .rectangulo-pequeno-bebecito31 {\r\n            grid-row: 1;\r\n\r\n            h3 {\r\n                font-size: 1.4rem;\r\n                font-weight: $bold;\r\n                margin: 0 0 0 0;\r\n                padding: 0 0 0 0;\r\n            }\r\n        }\r\n\r\n\r\n        .rectangulo-pequeno-bebecito32 {\r\n            grid-row: 2;\r\n            img {\r\n                max-width: 17rem;\r\n                max-height: 17rem;\r\n            }\r\n\r\n            h3 {\r\n                font-size: 1.4rem;\r\n                font-weight: $bold;\r\n                margin: 0 0 0 0;\r\n                padding: 0 0 0 0;\r\n            }\r\n        }\r\n    }\r\n\r\n\r\n    .rectangulo-pequeno-bebe4 {\r\n        grid-row: 2;\r\n        grid-column: 2;\r\n        display: grid;\r\n        margin-right: 1rem;\r\n        grid-template-rows: 2fr 3fr;\r\n        background-color: #fff;\r\n        height: 100%;\r\n        padding-top: 1rem;\r\n        margin-bottom: 2rem;\r\n        border-bottom-right-radius: 1rem;\r\n        padding-right: 1rem;\r\n\r\n        .rectangulo-pequeno-bebecito41 {\r\n            grid-row: 1;\r\n            display: inline-block;\r\n            justify-content: center;\r\n            align-items: center;\r\n            padding: 0;\r\n            margin: 0;\r\n\r\n            p {\r\n                font-size: 1.9rem;\r\n                padding: 0;\r\n                margin: 0;\r\n                text-align: center;\r\n                font-weight: bold;\r\n            }\r\n\r\n\r\n\r\n            h3 {\r\n                font-size: 1.3rem;\r\n                font-weight: $bold;\r\n                margin: 0;\r\n                padding: 0;\r\n            }\r\n\r\n        }\r\n\r\n        .rectangulo-pequeno-bebecito42 {\r\n            grid-row: 2;\r\n            margin: 0;\r\n            padding: 0;\r\n\r\n            p {\r\n                padding: 0;\r\n                margin: 0;\r\n                font-size: 2.4rem;\r\n                text-align: center;\r\n                font-weight: bold;\r\n            }\r\n\r\n            h3 {\r\n                font-size: 1.3rem;\r\n                font-weight: $bold;\r\n                margin: 0;\r\n                padding: 0;\r\n                text-align: center;\r\n            }\r\n        }\r\n    }\r\n\r\n}\r\n\r\n//total\r\n.rectangulo-grande-horizontal {\r\n    grid-row: 2 / 3;\r\n    grid-column: 2 / 3;\r\n    background-color: #d9f4e1;\r\n    border: 1px solid #ccc;\r\n    border-radius: 1rem;\r\n    justify-content: center;\r\n    align-items: center;\r\n    padding: 0 5px;\r\n    font-size: 1.2rem;\r\n    display: grid;\r\n    grid-template-rows: auto auto;\r\n    grid-template-columns: 1fr 1fr 1fr 1fr;\r\n    box-shadow: 5px 5px 5px rgba(0, 0, 0, 0.5);\r\n    margin-top: 0;\r\n    margin-bottom: 0;\r\n\r\n    @media (min-width: #{$telefono-1}){\r\n        grid-row: 3/4;\r\n        grid-column: 1;\r\n    //   height: min-content;\r\n\r\n    }\r\n\r\n    @media (min-width: #{$tablet}){\r\n\r\n        grid-row: 3/4;\r\n        grid-column: 1;\r\n      \r\n    }\r\n\r\n    @media (min-width: #{$laptop-1}){\r\n\r\n        grid-row: 2 / 3;\r\n        grid-column: 2 / 3;\r\n        // height: max-content;\r\n\r\n    }\r\n\r\n\r\n\r\n\r\n\r\n    h3 {\r\n        font-weight: $bold;\r\n        margin: 0;\r\n        padding: 0;\r\n    }\r\n\r\n    .rectangulo-grande-horizontal-bebe1 {\r\n        grid-row: 1;\r\n        grid-column: 1;\r\n        display: flex;\r\n        margin: 0;\r\n        padding: 0;\r\n        align-items: center;\r\n        justify-content: right;\r\n\r\n        h3 {\r\n            font-size: 1.7rem;\r\n            font-weight: $bold;\r\n            margin: 0;\r\n            padding: 0;\r\n            text-align: center;\r\n        }\r\n    }\r\n\r\n    .rectangulo-grande-horizontal-bebe2 {\r\n        grid-row: 1;\r\n        grid-column: 2/5;\r\n        margin: 0;\r\n        padding: 0;\r\n\r\n        h3 {\r\n            font-size: 3.7rem;\r\n            font-weight: $bold;\r\n            margin: 0;\r\n            padding: 0;\r\n        }\r\n    }\r\n\r\n    .rectangulo-grande-horizontal-bebe3 {\r\n        grid-row: 2;\r\n        grid-column: 1/4;\r\n        padding: 0;\r\n        display: flex;\r\n        justify-content: center;\r\n\r\n        .boton-azul-block {\r\n            width: auto;\r\n            width: 90%;\r\n            height: 5.8rem;\r\n            margin: 0 0 6px 0;\r\n            text-align: center;\r\n            @include fondo-radial(rgb(0, 81, 255));\r\n            border-radius: 1.2rem;\r\n            font-size: 3rem;\r\n            padding: 0;\r\n            display: flex;\r\n            justify-content: center;\r\n            align-items: center;\r\n\r\n            &:hover {\r\n                background-color: darken($azul, 26);\r\n                cursor: pointer;\r\n                border: solid 2px #FFEA00;\r\n\r\n                span {\r\n                    color: #FFEA00;\r\n                }\r\n            }\r\n\r\n            span {\r\n                color: $amarillo;\r\n            }\r\n\r\n        }\r\n\r\n    }\r\n\r\n    .rectangulo-grande-horizontal-bebe4 {\r\n        grid-row: 2;\r\n        grid-column: 4;\r\n        margin: 0;\r\n        padding-right: 8px;\r\n        padding-bottom: 8px;\r\n        display: flex;\r\n        flex-direction: column;\r\n        justify-content: center;\r\n        align-items: center;\r\n\r\n        h3 {\r\n            font-size: 1rem;\r\n        }\r\n    }\r\n}\r\n\r\n// fecha\r\n.rectangulo-pequeno-1 {\r\n    background-color: #e0e0e0;\r\n    border: 1px solid #ccc;\r\n    display: grid;\r\n    grid-template-columns: auto auto;\r\n    align-items: center;\r\n    padding: 0 1rem;\r\n    height: 22px;\r\n    border-radius: 1rem;\r\n}\r\n\r\n.fecha {\r\n    grid-column: 1;\r\n    display: flex;\r\n    align-items: center;\r\n}\r\n\r\n.fecha p {\r\n    font-size: 1.3rem;\r\n    font-weight: bold;\r\n    margin: 0 0 0 5rem;\r\n}\r\n\r\n.hora {\r\n    grid-column: 2;\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 0.5rem;\r\n    justify-content: flex-end;\r\n\r\n    img {\r\n        max-width: 15px;\r\n        max-height: 15px;\r\n        background-color: transparent;\r\n    }\r\n\r\n    p {\r\n        font-size: 1.3rem;\r\n        font-weight: bold;\r\n        margin: 0 5rem 0 0;\r\n\r\n    }\r\n}\r\n\r\n//animacionverde\r\n.rectangulo-pequeno-1 {\r\n    position: relative;\r\n    /* Para contener el pseudo-elemento */\r\n    overflow: hidden;\r\n    /* Asegura que el pseudo-elemento no sobresalga */\r\n    background-color: #fff;\r\n    border: solid 1px rgb(0, 255, 0);\r\n    box-shadow: 5px 5px 5px rgba(0, 0, 0, 0.5);\r\n    padding-bottom: 5px;\r\n}\r\n\r\n.rectangulo-pequeno-1::before {\r\n    content: \"\";\r\n    /* Pseudo-elemento para el fondo animado */\r\n    position: absolute;\r\n    top: 0;\r\n    left: 0;\r\n    height: 100%;\r\n    width: 0;\r\n    /* Comienza invisible */\r\n    background-color: rgba(0, 255, 0, 0.9);\r\n    z-index: 0;\r\n    animation: carga-verde 2s linear infinite;\r\n}\r\n\r\n@keyframes carga-verde {\r\n    0% {\r\n        width: 0;\r\n        /* Comienza sin mostrar */\r\n    }\r\n\r\n    100% {\r\n        width: 100%;\r\n        /* Llena el ancho completo */\r\n    }\r\n}\r\n\r\n.fecha,\r\n.hora {\r\n    position: relative;\r\n\r\n}\r\n\r\n\r\n.modal,\r\n.modal--manual,\r\n.modal--nombre,\r\n.modal--granel,\r\n.modal--cantidad,\r\n.modal--eliminar,\r\n.modal--eliminarCarrito,\r\n.modal--pagar, .modal--inventarioEliminar {\r\n    position: fixed;\r\n    top: 0;\r\n    left: 0;\r\n    right: 0;\r\n    bottom: 0;\r\n    background-color: #111111bd;\r\n    display: flex;\r\n    opacity: 0;\r\n    pointer-events: none;\r\n    transition: opacity .6s .9s;\r\n    --transform: translateY(-100vh);\r\n    --transition: transform .8s;\r\n\r\n    &--show {\r\n        opacity: 1;\r\n        pointer-events: unset;\r\n        transition: opacity .6s;\r\n        --transform: translateY(0);\r\n        --transition: transform .8s .8s;\r\n    }\r\n\r\n    &__container {\r\n        margin: auto;\r\n        width: 90%;\r\n        max-width: 500px;\r\n        max-height: 100%;\r\n        background-color: #fff;\r\n        border-radius: 6px;\r\n        padding: 1rem 2.5rem 1rem 2.5rem;\r\n        display: grid;\r\n        gap: 1rem;\r\n        place-items: center;\r\n        grid-auto-columns: 100%;\r\n        transform: var(--transform);\r\n        transition: var(--transition);\r\n    }\r\n\r\n    &__title {\r\n        font-size: 2.6rem;\r\n        margin: 0;\r\n        font-weight: 400;\r\n    }\r\n\r\n    &__paragraph {\r\n        margin-bottom: 8px;\r\n        margin-top: 0;\r\n        text-align: center;\r\n        font-size: 1.4rem;\r\n        font-weight: 400;\r\n\r\n    }\r\n\r\n    &__img {\r\n        width: 90%;\r\n        max-width: 180px;\r\n    }\r\n\r\n    &__close {\r\n        text-decoration: none;\r\n        color: #fff;\r\n        background-color: #0c21dd;\r\n        padding: 1rem 3rem;\r\n        border: 1px solid;\r\n        border-radius: 6px;\r\n        display: inline-block;\r\n        font-weight: bold;\r\n        transition: background-color .3s;\r\n        cursor: pointer;\r\n        margin-bottom: 1rem;\r\n        box-shadow: 0px 4px 6px rgba(0, 0, 0, 0.1);\r\n    }\r\n\r\n    &__close:hover {\r\n        color: #0c21dd;\r\n        background-color: #fff;\r\n        border: 2px solid;\r\n        box-shadow: 0px 4px 6px rgba(0, 0, 0, 0.2);\r\n    }\r\n}\r\n\r\n.modal--manual,\r\n.modal--nombre {\r\n    &__img {\r\n        margin-top: 1rem;\r\n        width: 90%;\r\n        max-width: 60px;\r\n    }\r\n\r\n    &__close {\r\n        color: $negro;\r\n    }\r\n\r\n    input {\r\n\r\n        display: flex;\r\n        justify-content: center;\r\n    }\r\n\r\n    input::placeholder {\r\n        color: $blanco;\r\n        font-size: small;\r\n\r\n    }\r\n\r\n    input::placeholder:hover {\r\n        color: $negro;\r\n\r\n    }\r\n\r\n}\r\n\r\n.modal--granel,\r\n.modal--cantidad,\r\n.modal--nombre,\r\n.modal--manual {\r\n    &__gridcantidad {\r\n        display: grid;\r\n        gap: 3rem;\r\n        max-height: 3rem;\r\n        grid-template-columns: 5fr 1fr;\r\n        margin: 0;\r\n        padding: 0;\r\n\r\n    }\r\n\r\n    &__gridprecio {\r\n        display: grid;\r\n        gap: 4.5rem;\r\n        grid-template-columns: 1fr 3fr;\r\n        margin: 0;\r\n        margin-bottom: 0;\r\n        padding: 0;\r\n\r\n    }\r\n\r\n\r\n    &__cantidad {\r\n        grid-column: 1;\r\n        display: flow-root;\r\n        align-items: center;\r\n\r\n\r\n\r\n\r\n    }\r\n\r\n    &__precio {\r\n        grid-column: 2;\r\n\r\n        h2 {\r\n            font-size: 4rem;\r\n            font-weight: bold;\r\n            display: unset;\r\n            text-align: center;\r\n            margin-bottom: 1rem;\r\n\r\n        }\r\n\r\n    }\r\n\r\n    &__gramos {\r\n        grid-column: 2;\r\n        display: flex;\r\n        align-items: flex-end;\r\n        justify-content: center;\r\n\r\n        p {\r\n            font-size: 3rem;\r\n            text-align: center;\r\n            display: contents;\r\n        }\r\n\r\n\r\n    }\r\n\r\n    &__titulo {\r\n        grid-column: 1;\r\n\r\n        h2 {\r\n            font-size: large;\r\n            font-weight: normal;\r\n            display: flex;\r\n        }\r\n\r\n    }\r\n\r\n\r\n    &__img {\r\n        margin-top: 0.8rem;\r\n\r\n    }\r\n\r\n    input {\r\n\r\n        display: flex;\r\n        justify-content: center;\r\n    }\r\n\r\n    input::placeholder {\r\n        color: $blanco;\r\n        font-size: small;\r\n\r\n    }\r\n\r\n    input::placeholder:hover {\r\n        color: $negro;\r\n\r\n    }\r\n\r\n\r\n}\r\n\r\n.modal--cantidad,\r\n.modal--granel,\r\n.modal--nombre,\r\n.modal--manual {\r\n    &__fleximg {\r\n        display: flex;\r\n        justify-content: center;\r\n        align-items: center;\r\n        position: relative;\r\n        width: 100%;\r\n        height: 100%;\r\n    }\r\n\r\n    &__fleximg1 {\r\n        display: flex;\r\n        justify-content: center;\r\n        align-items: center;\r\n        z-index: 1;\r\n        padding-top: 4px;\r\n\r\n\r\n    }\r\n\r\n    &__fleximg2 {\r\n        position: absolute;\r\n        top: 3px;\r\n        right: 0;\r\n        transition: background-color .3s;\r\n        cursor: pointer;\r\n        filter: invert(1) brightness(60%) grayscale(100%);\r\n    }\r\n\r\n    &__fleximg2:hover {\r\n        filter: none;\r\n    }\r\n\r\n    &__img1 {\r\n        // margin-top: 1rem;\r\n        max-width: 20px;\r\n    }\r\n\r\n    &__img2 {\r\n        // margin-top: 1rem;\r\n        // width: 90%;\r\n        max-width: 35px;\r\n        max-height: 35px;\r\n        cursor: pointer;\r\n    }\r\n\r\n    &__precio {\r\n        grid-column: 2;\r\n        display: flex;\r\n        justify-content: center;\r\n        align-items: center;\r\n\r\n\r\n        h2 {\r\n            font-size: 4rem;\r\n            font-weight: bold;\r\n            display: unset;\r\n            text-align: center;\r\n            margin-top: 0;\r\n\r\n        }\r\n\r\n    }\r\n\r\n    &__gridprecio {\r\n        display: grid;\r\n        gap: 4.5rem;\r\n        grid-template-columns: 1fr 3fr;\r\n        margin: 0;\r\n        margin-bottom: 0;\r\n        padding: 0;\r\n\r\n\r\n    }\r\n\r\n    &__container {\r\n        padding: 1rem 2.5rem 1rem 2.5rem;\r\n        overflow-y: auto;\r\n    }\r\n\r\n    &__cerrar {\r\n        text-decoration: none;\r\n        background-color: transparent;\r\n        padding: 0;\r\n        border: none;\r\n        border-radius: 0;\r\n        transition: background-color .3s;\r\n\r\n\r\n    }\r\n\r\n    &__cerrar:hover {\r\n        filter: saturate(9) hue-rotate(0deg) contrast(1.2);\r\n    }\r\n\r\n\r\n}\r\n\r\n\r\n.modal--cantidad,\r\n.modal--granel,\r\n.modal--manual,\r\n.modal--nombre {\r\n    &__container {\r\n        gap: 0;\r\n        max-height: 100%;\r\n    }\r\n\r\n    &__img1 {\r\n        height: 2.6rem;\r\n    }\r\n\r\n    &__title {\r\n        font-size: 2.2rem;\r\n    }\r\n\r\n    &__paragraph {\r\n        padding: 0 0 1rem 0;\r\n    }\r\n\r\n    &__caracteristicas {\r\n        display: grid;\r\n        grid-template-columns: repeat(5, auto);\r\n        grid-template-rows: 1fr 1fr;\r\n    }\r\n\r\n    &__fila1-cantidad,\r\n    &__fila1-nombre,\r\n    &__fila1-descripcion,\r\n    &__fila1-costoventa,\r\n    &__fila1-total {\r\n        grid-row: 1;\r\n        margin-top: 2rem;\r\n        padding-top: 0;\r\n        display: flex;\r\n        align-items: center;\r\n        justify-content: left;\r\n        height: 2.4rem;\r\n\r\n        p {\r\n            font-weight: bold;\r\n            padding: 0 3px;\r\n            font-size: 1.1rem;\r\n            align-items: center;\r\n\r\n        }\r\n\r\n    }\r\n\r\n    &__fila2-cantidad,\r\n    &__fila2-nombre,\r\n    &__fila2-descripcion,\r\n    &__fila2-costoventa,\r\n    &__fila2-total {\r\n        grid-row: 2;\r\n        border: solid 1px #7cf77c;\r\n        display: flex;\r\n        align-items: center;\r\n        justify-content: left;\r\n        max-height: min-content;\r\n\r\n        p {\r\n            font-size: 1.1rem;\r\n            padding: 0 2px;\r\n            margin: 0 2px;\r\n        }\r\n    }\r\n\r\n\r\n    &__fila1-cantidad {\r\n        grid-column: 1;\r\n    }\r\n\r\n    &__fila1-nombre {\r\n        grid-column: 2;\r\n    }\r\n\r\n    &__fila1-descripcion {\r\n        grid-column: 3;\r\n    }\r\n\r\n    &__fila1-costoventa {\r\n        grid-column: 4;\r\n    }\r\n\r\n    &__fila1-total {\r\n        grid-column: 5;\r\n    }\r\n\r\n    &__fila2-cantidad {\r\n        grid-column: 1;\r\n    }\r\n\r\n    &__fila2-nombre {\r\n        grid-column: 2;\r\n    }\r\n\r\n    &__fila2-descripcion {\r\n        grid-column: 3;\r\n    }\r\n\r\n    &__fila2-costoventa {\r\n        grid-column: 4;\r\n    }\r\n\r\n    &__fila2-total {\r\n        grid-column: 5;\r\n    }\r\n\r\n    &__boton {\r\n        display: flex;\r\n    }\r\n\r\n    &__titulo {\r\n        display: flex;\r\n        justify-content: center;\r\n        align-items: center;\r\n        padding: 0;\r\n\r\n    }\r\n\r\n    &__btn {\r\n        background-color: #03aa03;\r\n        color: #fff;\r\n        padding: 1rem 2rem;\r\n        border-radius: